/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by compat/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { Add, And, KroneckerDelta, Mul, Piecewise, Pow, S, Sym, deltaproduct, deltasummation, mul, oo, rational, rel } from '../../src';
import { sympyStr } from '../sympy-str';
import { equivalent } from '../sympy-equivalent';

describe("doctests of sympy.concrete.delta", () => {
  it("deltasummation(KroneckerDelta(i, k), (k, -oo, oo))", () => {
    const k = new Sym('k');
    const i = new Sym('i', { integer: true, finite: true });
    expect(sympyStr(deltasummation(KroneckerDelta(i, k), [k, S.NegativeInfinity, oo]))).toBe('1');
  });
  it("deltasummation(KroneckerDelta(i, k), (k, 0, oo))", () => {
    const k = new Sym('k');
    const i = new Sym('i', { integer: true, finite: true });
    expect(sympyStr(deltasummation(KroneckerDelta(i, k), [k, 0, oo]))).toBe('Piecewise((1, i >= 0), (0, True))');
  });
  it("deltasummation(KroneckerDelta(i, k), (k, 1, 3))", () => {
    const k = new Sym('k');
    const i = new Sym('i', { integer: true, finite: true });
    expect(sympyStr(deltasummation(KroneckerDelta(i, k), [k, 1, 3]))).toBe('Piecewise((1, (i >= 1) & (i <= 3)), (0, True))');
  });
  it("deltasummation(k*KroneckerDelta(i, j)*KroneckerDelta(j, k), (k, -oo, oo))", () => {
    const k = new Sym('k');
    const i = new Sym('i', { integer: true, finite: true });
    const j = new Sym('j', { integer: true, finite: true });
    expect(sympyStr(deltasummation(mul(k, KroneckerDelta(i, j), KroneckerDelta(j, k)), [k, S.NegativeInfinity, oo]))).toBe('j*KroneckerDelta(i, j)');
  });
  it("deltasummation(j*KroneckerDelta(i, j), (j, -oo, oo))", () => {
    const j = new Sym('j', { integer: true, finite: true });
    const i = new Sym('i', { integer: true, finite: true });
    expect(sympyStr(deltasummation(mul(j, KroneckerDelta(i, j)), [j, S.NegativeInfinity, oo]))).toBe('i');
  });
  it("deltasummation(i*KroneckerDelta(i, j), (i, -oo, oo))", () => {
    const i = new Sym('i', { integer: true, finite: true });
    const j = new Sym('j', { integer: true, finite: true });
    expect(sympyStr(deltasummation(mul(i, KroneckerDelta(i, j)), [i, S.NegativeInfinity, oo]))).toBe('j');
  });
});

